from datetime import datetime, timedelta
from collections import defaultdict
from typing import Dict, List, Optional
import psycopg2
from psycopg2.extras import RealDictCursor
import sys

sys.path.append('../..')
from config import Config


class AnalyticsService:
    """
    Service for querying and analyzing URL click data.

    Provides methods for:
    - Aggregate statistics
    - Time-series analysis
    - Geographic distribution
    - Referrer tracking
    - Performance metrics
    """

    def __init__(self):
        self.conn = self._get_connection()

    def _get_connection(self):
        """Connect to PostgreSQL for analytics queries"""
        return psycopg2.connect(
            host=Config.DB_REPLICA_HOST,  # Read from replica for analytics
            port=Config.DB_REPLICA_PORT,
            database=Config.DB_NAME,
            user=Config.DB_USER,
            password=Config.DB_PASSWORD,
            cursor_factory=RealDictCursor  # Return rows as dictionaries
        )

    def get_url_summary(self, short_url: str) -> Optional[Dict]:

        cursor = self.conn.cursor()

        cursor.execute("""
            SELECT 
                u.url,
                u.short_url,
                u.clicks as total_clicks,
                u.created_at,
                u.last_accessed,
                u.status,
                u.created_by,
                COUNT(DISTINCT c.ip_address) as unique_ips
            FROM urls u
            LEFT JOIN click_events c ON u.short_url = c.short_url
            WHERE u.short_url = %s
            GROUP BY u.id
        """, (short_url,))

        result = cursor.fetchone()
        cursor.close()

        return dict(result) if result else None

    def get_clicks_over_time(
            self,
            short_url: str,
            interval: str = 'hour',
            days: int = 7
    ) -> List[Dict]:
        """
        Get time-series click data.

        Args:
            short_url: Short URL code
            interval: 'hour', 'day', or 'week'
            days: Number of days to look back

        Returns:
            [
                {'time_bucket': '2025-01-20 14:00:00', 'clicks': 45},
                {'time_bucket': '2025-01-20 15:00:00', 'clicks': 67},
                ...
            ]
        """
        cursor = self.conn.cursor()

        # Map interval to PostgreSQL date_trunc parameter
        interval_map = {
            'hour': 'hour',
            'day': 'day',
            'week': 'week'
        }

        cursor.execute(f"""
            SELECT 
                date_trunc(%s, clicked_at) as time_bucket,
                COUNT(*) as clicks
            FROM click_events
            WHERE short_url = %s
                AND clicked_at >= NOW() - INTERVAL '{days} days'
            GROUP BY time_bucket
            ORDER BY time_bucket
        """, (interval_map.get(interval, 'hour'), short_url))

        results = cursor.fetchall()
        cursor.close()

        return [dict(row) for row in results]

    def get_top_referrers(self, short_url: str, limit: int = 10) -> List[Dict]:
        """
        Get top traffic sources (referrers).

        Returns:
            [
                {'referrer': 'https://google.com', 'clicks': 234},
                {'referrer': 'https://twitter.com', 'clicks': 156},
                ...
            ]
        """
        cursor = self.conn.cursor()

        cursor.execute("""
            SELECT 
                COALESCE(referrer, 'Direct') as referrer,
                COUNT(*) as clicks
            FROM click_events
            WHERE short_url = %s
            GROUP BY referrer
            ORDER BY clicks DESC
            LIMIT %s
        """, (short_url, limit))

        results = cursor.fetchall()
        cursor.close()

        return [dict(row) for row in results]

    def get_geographic_distribution(self, short_url: str) -> List[Dict]:
        """
        Get clicks by country.

        Returns:
            [
                {'country': 'United States', 'clicks': 523},
                {'country': 'United Kingdom', 'clicks': 187},
                ...
            ]
        """
        cursor = self.conn.cursor()

        cursor.execute("""
            SELECT 
                COALESCE(country, 'Unknown') as country,
                COUNT(*) as clicks
            FROM click_events
            WHERE short_url = %s
            GROUP BY country
            ORDER BY clicks DESC
        """, (short_url,))

        results = cursor.fetchall()
        cursor.close()

        return [dict(row) for row in results]

    def get_device_breakdown(self, short_url: str) -> Dict:
        """
        Analyze user agents to determine device types.

        Returns:
            {
                'mobile': 456,
                'desktop': 789,
                'tablet': 123,
                'bot': 45
            }
        """
        cursor = self.conn.cursor()

        cursor.execute("""
            SELECT user_agent, COUNT(*) as count
            FROM click_events
            WHERE short_url = %s AND user_agent IS NOT NULL
            GROUP BY user_agent
        """, (short_url,))

        results = cursor.fetchall()
        cursor.close()

        # Categorize based on user agent strings
        device_counts = defaultdict(int)

        for row in results:
            user_agent = row['user_agent'].lower()
            count = row['count']

            if 'bot' in user_agent or 'crawler' in user_agent:
                device_counts['bot'] += count
            elif 'mobile' in user_agent or 'android' in user_agent or 'iphone' in user_agent:
                device_counts['mobile'] += count
            elif 'tablet' in user_agent or 'ipad' in user_agent:
                device_counts['tablet'] += count
            else:
                device_counts['desktop'] += count

        return dict(device_counts)

    def get_peak_hours(self, short_url: str) -> List[Dict]:
        """
        Get clicks by hour of day (0-23).

        Returns:
            [
                {'hour': 0, 'clicks': 45},
                {'hour': 1, 'clicks': 23},
                ...
            ]
        """
        cursor = self.conn.cursor()

        cursor.execute("""
            SELECT 
                EXTRACT(HOUR FROM clicked_at) as hour,
                COUNT(*) as clicks
            FROM click_events
            WHERE short_url = %s
            GROUP BY hour
            ORDER BY hour
        """, (short_url,))

        results = cursor.fetchall()
        cursor.close()

        # Convert Decimal to int for hour
        return [{'hour': int(row['hour']), 'clicks': row['clicks']} for row in results]

    def get_global_statistics(self) -> Dict:
        """
        Get system-wide statistics.

        Returns:
            {
                'total_urls': 15234,
                'total_clicks': 2456789,
                'active_urls': 14890,
                'expired_urls': 344,
                'avg_clicks_per_url': 161.2
            }
        """
        cursor = self.conn.cursor()

        cursor.execute("""
            SELECT 
                COUNT(*) as total_urls,
                SUM(clicks) as total_clicks,
                COUNT(*) FILTER (WHERE status = 'active' AND 
                    (expiration_time IS NULL OR expiration_time > NOW())) as active_urls,
                COUNT(*) FILTER (WHERE status = 'active' AND 
                    expiration_time IS NOT NULL AND expiration_time <= NOW()) as expired_urls,
                AVG(clicks) as avg_clicks_per_url
            FROM urls
        """)

        result = cursor.fetchone()
        cursor.close()

        return dict(result) if result else {}

    def get_top_urls(self, limit: int = 10, days: Optional[int] = None) -> List[Dict]:

        cursor = self.conn.cursor()

        if days:
            cursor.execute("""
                SELECT 
                    u.short_url,
                    u.url,
                    COUNT(c.id) as recent_clicks
                FROM urls u
                JOIN click_events c ON u.short_url = c.short_url
                WHERE c.clicked_at >= NOW() - INTERVAL '%s days'
                GROUP BY u.short_url, u.url
                ORDER BY recent_clicks DESC
                LIMIT %s
            """, (days, limit))
        else:
            cursor.execute("""
                SELECT 
                    short_url,
                    url,
                    clicks
                FROM urls
                ORDER BY clicks DESC
                LIMIT %s
            """, (limit,))

        results = cursor.fetchall()
        cursor.close()

        return [dict(row) for row in results]

    def close(self):
        """Close database connection"""
        if self.conn:
            self.conn.close()


